SELECT f.id::text,f.actor_id,f.subject,f.provider_access,f.absolute_expires,f.authenticated_at,t.expires_at FROM bearer_tokens t JOIN bearer_families f ON f.id=t.family_id JOIN actors a ON a.id=f.actor_id WHERE t.access_hash=$1 AND f.client_id=$2 AND f.issuer=$3 AND NOT f.revoked AND NOT t.used AND a.active AND t.expires_at>extract(epoch FROM clock_timestamp()) AND f.absolute_expires>extract(epoch FROM clock_timestamp())
